create or replace function public.ils_professional_security_review_decide(p_queue_id uuid,p_approval_decision text,p_approved_action text,p_reason text) returns boolean language plpgsql security definer set search_path=public as $$ declare q record; u uuid; begin u:=auth.uid(); if u is null or p_queue_id is null or p_approval_decision not in ('APPROVE','REJECT') or p_reason is null or length(trim(p_reason))<5 then return false; end if; if not public.ils_professional_security_reviewer_is_authorized(u) then return false; end if; select * into q from public.ils_professional_assignment_security_review_queue where id=p_queue_id for update; if not found then return false; end if; if q.review_status not in ('PENDING','IN_REVIEW') then return false; end if; if q.assigned_reviewer_id is not null and q.assigned_reviewer_id<>u then return false; end if; if q.source_failure_code is null and q.decision is null then return false; end if; if q.assigned_reviewer_id=u then null; end if; if p_approval_decision='APPROVE' then if p_approved_action is null then return false; end if; if not exists(select 1 from public.ils_professional_assignment_mutation_alert_escalation_rules r where r.decision=q.decision and r.action_code=p_approved_action and r.active=true and r.destructive_action_allowed=false) then return false; end if; update public.ils_professional_assignment_security_review_queue set review_status='APPROVED',assigned_reviewer_id=u,reviewer_note=trim(p_reason),reviewed_at=now() where id=p_queue_id; else update public.ils_professional_assignment_security_review_queue set review_status='REJECTED',assigned_reviewer_id=u,reviewer_note=trim(p_reason),reviewed_at=now() where id=p_queue_id; end if; insert into public.ils_professional_assignment_security_review_approval_log(queue_id,reviewer_id,approval_decision,approved_action,approval_reason) values(q.id,u,p_approval_decision,p_approved_action,trim(p_reason)); return true; end; $$; revoke all on function public.ils_professional_security_review_decide(uuid,text,text,text) from public,anon,authenticated; grant execute on function public.ils_professional_security_review_decide(uuid,text,text,text) to authenticated; create table if not exists public.ils_professional_security_review_approval_gate_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_review_approval_gate_tests enable row level security; alter table public.ils_professional_security_review_approval_gate_tests force row level security; revoke all on public.ils_professional_security_review_approval_gate_tests from anon,authenticated; insert into public.ils_professional_security_review_approval_gate_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('AUTH_REQUIRED','BLOCK','BLOCK',true,'Decision requires an authenticated reviewer.'),('REVIEWER_AUTH','BLOCK_UNAUTHORIZED','BLOCK_UNAUTHORIZED',true,'Only explicitly authorized security reviewers qualify.'),('QUEUE_NOT_FOUND','BLOCK','BLOCK',true,'Unknown queue item is rejected.'),('QUEUE_STATE_CLOSED','BLOCK','BLOCK',true,'Only pending/in-review items can be decided.'),('ASSIGNED_OTHER_REVIEWER','BLOCK','BLOCK',true,'Reviewer assignment prevents unauthorized takeover.'),('REASON_REQUIRED','BLOCK','BLOCK',true,'Approval/rejection requires a meaningful reason.'),('APPROVE_ACTION_REQUIRED','BLOCK','BLOCK',true,'Approval requires an explicit action.'),('ACTION_SCOPE_MISMATCH','BLOCK','BLOCK',true,'Only an active configured action matching the queue decision is approvable.'),('DESTRUCTIVE_ACTION','BLOCK','BLOCK',true,'Destructive actions cannot be approved by this function.'),('REJECT_PATH','ALLOW','ALLOW',true,'Authorized reviewer may reject with an audit reason.'),('APPROVE_PATH','CONTROLLED_ALLOW','CONTROLLED_ALLOW',true,'Authorized reviewer may approve only an exact configured non-destructive action.'),('AUDIT_RECORD','REQUIRED','REQUIRED',true,'Every decision writes an approval log.'),('CONCURRENT_DECISION','BLOCK_STALE','BLOCK_STALE',true,'Row locking plus queue-state check prevents double decision.'),('LIVE_E2E','PENDING_AUTH_SESSION','PENDING_AUTH_SESSION',true,'No live reviewer authorization or queue item exists in TEST; no fake E2E result.');